from bisect import bisect_left, bisect_right


def is_majority(arr, n, x):
    """Write a function to check for majority element in the given sorted array.

    Return True if ``x`` occurs more than ``n / 2`` times among the
    first ``n`` elements of the sorted array ``arr``, otherwise False.
    """
    if n is None or n <= 0:
        return False
    try:
        length = len(arr)
    except TypeError:
        return False
    if length == 0:
        return False
    limit = min(n, length)
    first = bisect_left(arr, x, 0, limit)
    if first >= limit or arr[first] != x:
        return False
    count = bisect_right(arr, x, first, limit) - first
    return count * 2 > n
